<?php
declare(strict_types=1); require_once __DIR__.'/bootstrap.php';
$adminCount=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();
if ($adminCount>0) { http_response_code(403); exit('First-admin setup is closed because an administrator already exists. Delete or disable setup.php.'); }
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { admin_csrf_check(); $name=trim((string)($_POST['full_name']??'')); $email=strtolower(trim((string)($_POST['email']??''))); $password=(string)($_POST['password']??''); $confirm=(string)($_POST['confirm_password']??''); if ($name==='' || mb_strlen($name)>150) $error='Enter your name (up to 150 characters).'; elseif (!filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($email)>190) $error='Enter a valid email address.'; elseif (strlen($password)<12) $error='Use a password of at least 12 characters.'; elseif ($password!==$confirm) $error='The passwords do not match.'; else { try { $pdo->beginTransaction(); $count=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin' FOR UPDATE")->fetchColumn(); if ($count>0) { $pdo->rollBack(); http_response_code(403); exit('An administrator was already created. Setup is closed.'); } $stmt=$pdo->prepare("INSERT INTO users (full_name,email,password_hash,role,status) VALUES (?,?,?,'admin','active')"); $stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]); $pdo->commit(); $_SESSION['flash']='Administrator created. Sign in using your new credentials.'; redirect('login.php'); } catch (PDOException $ex) { if($pdo->inTransaction()) $pdo->rollBack(); $error=$ex->getCode()==='23000'?'That email address is already registered.':'Could not create the administrator. Check the PHP/server error log.'; } } }
