mb-3"><label class="form-label">Admin email</label><input class="form-control" type="email" name="email" maxlength="190" required value="<?= e((string)($_POST['email']??'')) ?>"></div><div class="mb-3"><label class="form-label">Password (minimum 12 characters)</label><input class="form-control" type="password" name="password" minlength="12" required autocomplete="new-password"></div><div class="mb-3"><label class="form-label">Confirm password</label><input class="form-control" type="password" name="confirm_password" minlength="12" required autocomplete="new-password"></div><button class="btn btn-primary w-100">Create administrator</button></form><p class="small text-danger mt-3 mb-0">After setup, delete admin/setup.php from your project.</p></main><script src="../assets/js/app.js"></script></body></html>
